use std::arch::x86_64::_mm_prefetch;

/// SAFETY: p must be a valid readable address (we hold &Node, so it is).
unsafe fn prefetch_l2(p: *const u8) {
    #[cfg(target_arch = "x86_64")]
    _mm_prefetch(p as *const i8, std::arch::x86_64::_MM_HINT_T1);
}

// the idiomatic Rust answer for a chase: an arena. Nodes in one Vec, traverse
// by index - the indices are sequential so the access streams, no hint needed.
struct Arena { nodes: Vec<Node> }   // Node { children: [u32; 4], value: f64 }

